def make_textbook_entry(content_dict, length="medium", ttype="unit_lesson", tags=None):
    return {
        "subject": content_dict["subject"], "topic": content_dict["topic"], "level": content_dict["level"],
        "length": length, "type": ttype, "title": content_dict["title"],
        "tags": tags or [], "content": content_dict,
        "status": "published", "source": "claude_max_seed_batch05",
    }

textbooks = [
    make_textbook_entry(DIFFERENTIATION, tags=["微分", "微分係数", "接線", "極値", "増減表"]),
    make_textbook_entry(INTEGRATION, tags=["積分", "不定積分", "定積分", "面積", "微積基本定理"]),
    make_textbook_entry(SEQUENCE, tags=["数列", "等差", "等比", "シグマ", "漸化式", "帰納法"]),
    make_textbook_entry(VECTOR_PLANE, tags=["ベクトル", "平面", "内積", "位置ベクトル", "内分点", "重心"]),
    make_textbook_entry(VECTOR_SPACE, tags=["ベクトル", "空間", "3次元", "四面体", "正四面体", "なす角"]),
]

